import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.blogCategories().listBlogCategories(Map.of("limit", 20, "offset", 0));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("blog_categories")) {
    Map<?, ?> category = (Map<?, ?>) row;
    System.out.println(category.get("id") + " " + category.get("name") + " " + category.get("url"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

